    WHERE {
      ?p1 a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player> ;
          <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/player_name> "Abdou Diallo" ;
          <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/player_api_id> ?id1 .
      ?pa1 a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
          <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?id1 ;
          <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/ball_control> ?bc1 .
    }
  }
  {
    SELECT (AVG(?bc2) AS ?avg2)
    WHERE {
      ?p2 a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player> ;
          <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/player_name> "Aaron Appindangoye" ;
          <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/player_api_id> ?id2 .
      ?pa2 a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
          <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?id2 ;
          <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/ball_control> ?bc2 .
    }
  }
}

SELECT ?player_name WHERE {
  ?p1 a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player> ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/player_name> "Aaron Lennon" ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/birthday> ?b1 .
  ?p2 a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player> ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/player_name> "Abdelaziz Barrada" ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/birthday> ?b2 .
  BIND(IF(?b1 < ?b2, "Aaron Lennon", "Abdelaziz Barrada") AS ?player_name)
}

SELECT ?name WHERE {
  ?ta a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/TeamAttributes> ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/TeamAttributes/date> ?date ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/TeamAttributes/buildupplaypassing> ?bpp ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/TeamAttributes/team_api_id> ?tid .
  FILTER(STRSTARTS(STR(?date), "2012"))
  {
    SELECT (AVG(?bpp2) AS ?avg) WHERE {
      ?ta2 a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/TeamAttributes> ;
           <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/TeamAttributes/date> ?date2 ;
           <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/TeamAttributes/buildupplaypassing> ?bpp2 .
      FILTER(STRSTARTS(STR(?date2), "2012"))
    }
  }
  FILTER(xsd:decimal(?bpp) > ?avg)
  ?team a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Team> ;
        <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Team/team_api_id> ?tid ;
        <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Team/team_long_name> ?name .
}

SELECT ?name (COUNT(?m) AS ?matchCount) WHERE {
  ?m a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Match> ;
     <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Match/league_id> ?lid .
  ?l a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/League> ;
     <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/League/id> ?lid ;
     <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/League/name> ?name .
}
GROUP BY ?name
ORDER BY DESC(?matchCount)
LIMIT 1

SELECT ?player_name WHERE {
  ?p a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player> ;
     <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/player_name> ?player_name ;
     <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/height> ?height .
}
ORDER BY DESC(xsd:long(?height))
LIMIT 1

SELECT (xsd:decimal(?leftCount) / xsd:decimal(?totalCount) * 100 AS ?percentage)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?p1) AS ?totalCount)
    WHERE {
      ?pa1 a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
           <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?papi1 .
      ?p1 a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player> ;
          <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/player_api_id> ?papi1 ;
          <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/birthday> ?b1 .
      BIND(SUBSTR(STR(?b1),1,4) AS ?y1)
      FILTER(?y1 >= "1987" && ?y1 <= "1992")
    }
  }
  {
    SELECT (COUNT(DISTINCT ?p2) AS ?leftCount)
    WHERE {
      ?pa2 a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
           <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?papi2 ;
           <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/preferred_foot> "left" .
      ?p2 a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player> ;
          <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/player_api_id> ?papi2 ;
          <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/birthday> ?b2 .
      BIND(SUBSTR(STR(?b2),1,4) AS ?y2)
      FILTER(?y2 >= "1987" && ?y2 <= "1992")
    }
  }
}

SELECT (COUNT(DISTINCT ?p) AS ?n) WHERE {
  ?pa a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?p ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/preferred_foot> ?foot ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/attacking_work_rate> ?awr .
  FILTER(LCASE(?foot) = "left")
  FILTER(LCASE(?awr) = "low")
}

SELECT (COUNT(DISTINCT ?p) AS ?n) WHERE {
  ?player a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player> ;
          <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/birthday> ?b ;
          <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/player_api_id> ?p .
  FILTER (?b < "1986-01-01 00:00:00")
  ?pa a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?p ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/defensive_work_rate> ?dwr .
  FILTER (?dwr = "high")
}

SELECT ?name (AVG(?ha) AS ?avgHeadingAccuracy) WHERE {
  ?p a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player> ;
     <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/player_name> ?name ;
     <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/height> ?height ;
     <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/player_api_id> ?apiId .
  FILTER(xsd:decimal(?height) > 180)
  ?pa a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?apiId ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/heading_accuracy> ?ha .
}
GROUP BY ?name
ORDER BY DESC(?avgHeadingAccuracy)
LIMIT 10

SELECT (AVG(?rating) AS ?avgRating) WHERE {
  ?p a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player> ;
     <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/player_name> "Pietro Marino" ;
     <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/player_api_id> ?apiId .
  ?pa a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?apiId ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/overall_rating> ?rating .
}

SELECT (((?r1 - ?r2)/?r2)*100 AS ?pctHigher) WHERE {
  {
    SELECT (MAX(?rating1) AS ?r1) WHERE {
      ?p1 a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player> ;
          <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/player_name> "Ariel Borysiuk" ;
          <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/player_api_id> ?id1 .
      ?pa1 a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
           <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?id1 ;
           <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/overall_rating> ?rating1 .
    }
  }
  {
    SELECT (MAX(?rating2) AS ?r2) WHERE {
      ?p2 a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player> ;
          <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/player_name> "Paulin Puel" ;
          <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/player_api_id> ?id2 .
      ?pa2 a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
           <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?id2 ;
           <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/overall_rating> ?rating2 .
    }
  }
}

SELECT (YEAR(NOW()) - YEAR(xsd:dateTime(?birthday)) AS ?age) WHERE {
  ?p a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player> ;
     <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/player_api_id> ?pid ;
     <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/birthday> ?birthday .
  ?pa a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?pid ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/sprint_speed> ?ss ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/PlayerAttributes/date> ?date .
  FILTER(xsd:decimal(?ss) >= 97)
  FILTER(?date >= "2013-01-01 00:00:00" && ?date <= "2015-12-31 23:59:59")
}

SELECT ?chancecreationpassing ?chancecreationpassingclass WHERE {
  ?team a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Team> ;
        <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Team/team_long_name> "Ajax" ;
        <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Team/team_api_id> ?teamApiId .
  ?ta a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/TeamAttributes> ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/TeamAttributes/team_api_id> ?teamApiId ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/TeamAttributes/chancecreationpassing> ?chancecreationpassing ;
      <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/TeamAttributes/chancecreationpassingclass> ?chancecreationpassingclass .
}
ORDER BY DESC(xsd:decimal(?chancecreationpassing))
LIMIT 1

SELECT ?name WHERE {
  {
    SELECT (MAX(?h) AS ?maxH) WHERE {
      ?p a <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player> ;
         <http://bird-bird_european_football_2-ontology-20261002-172845/ontology/vkg-bird_european_football_2/Player/height> ?h .
    }
  }
